#include <vector>
#include <algorithm>

class Solution {
public:
    long long maxSumOfMSubarraysVariable(std::vector<int>& nums, int m, int minLen) {
        int n = nums.size();
        if (n < m * minLen) return 0;
        std::vector<long long> pref(n + 1, 0);
        for (int i = 0; i < n; ++i) pref[i + 1] = pref[i] + nums[i];
        std::vector<std::vector<long long>> dp(m + 1, std::vector<long long>(n + 1, 0));
        for (int j = 1; j <= m; ++j) {
            long long bestDiff = -1e18;
            for (int i = minLen; i <= n; ++i) {
                bestDiff = std::max(bestDiff, dp[j - 1][i - minLen] - pref[i - minLen]);
                dp[j][i] = std::max(dp[j][i - 1], pref[i] + bestDiff);
            }
        }
        return dp[m][n];
    }
};

class Solution {
    public long maxSumOfMSubarraysVariable(int[] nums, int m, int minLen) {
        int n = nums.length;
        if (n < m * minLen) return 0;
        long[] pref = new long[n + 1];
        for (int i = 0; i < n; i++) pref[i + 1] = pref[i] + nums[i];
        long[][] dp = new long[m + 1][n + 1];
        for (int j = 1; j <= m; j++) {
            long bestDiff = Long.MIN_VALUE / 2;
            for (int i = minLen; i <= n; i++) {
                bestDiff = Math.max(bestDiff, dp[j - 1][i - minLen] - pref[i - minLen]);
                dp[j][i] = Math.max(dp[j][i - 1], pref[i] + bestDiff);
            }
        }
        return dp[m][n];
    }
}

